import { z } from 'zod';

export default function ContactForm() {
  async function submitContact(formData: FormData) {
    'use server';

    const schema = z.object({
      name: z.string().min(1, "Name is required"),
      email: z.string().email("Invalid email address"),
      message: z.string().min(1, "Message is required"),
    });

    const data = {
      name: formData.get('name'),
      email: formData.get('email'),
      message: formData.get('message'),
    };

    const result = schema.safeParse(data);

    if (!result.success) {
      console.error("Validation failed:", result.error.flatten().fieldErrors);
      // In a real application, you would handle errors here, 
      // perhaps by returning them to be displayed.
      return { success: false, errors: result.error.flatten().fieldErrors };
    }

    console.log("Form submitted successfully:", result.data);
    // Simulate saving data or sending email
    return { success: true };
  }

  return (
    <div style={{ maxWidth: '400px', margin: '20px auto', fontFamily: 'sans-serif' }}>
      <h2 style={{ marginBottom: '15px' }}>Contact Us</h2>
      <form action={submitContact} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
          <label htmlFor="name" style={{ fontWeight: 'bold' }}>Name</label>
          <input
            type="text"
            id="name"
            name="name"
            required
            style={{ padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }}
          />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
          <label htmlFor="email" style={{ fontWeight: 'bold' }}>Email</label>
          <input
            type="email"
            id="email"
            name="email"
            required
            style={{ padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }}
          />
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
          <label htmlFor="message" style={{ fontWeight: 'bold' }}>Message</label>
          <textarea
            id="message"
            name="message"
            required
            rows={4}
            style={{ padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }}
          />
        </div>

        <button
          type="submit"
          style={{
            padding: '10px 15px',
            backgroundColor: '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            fontWeight: 'bold'
          }}
        >
          Send Message
        </button>
      </form>
    </div>
  );
}

